// ── Preparar prompt para detección de modelos ───────────────────────────────
const text = $input.first().json.text || '';

if (!text || text.trim().length < 50) {
  throw new Error('El PDF no contiene suficiente texto. Es posible que sea un PDF de imágenes escaneadas (sin OCR).');
}

// Truncar a ~6000 chars para no superar el contexto del modelo
const truncated = text.substring(0, 6000);

const prompt = `Eres un experto en paneles solares fotovoltaicos. Analiza la siguiente ficha técnica y detecta TODOS los modelos de paneles solares disponibles en el documento.

Texto de la ficha técnica:
${truncated}

Instrucciones:
1. Identifica cada modelo de panel solar (suelen diferenciarse por la potencia pico en Watios, ej: 550W, 560W, 570W)
2. Extrae el nombre del fabricante
3. Para cada modelo, anota su potencia pico si la encuentras

Responde ÚNICAMENTE con un objeto JSON válido (sin texto extra, sin bloques markdown), con este formato:
{
  "manufacturer": "Nombre del fabricante",
  "models": [
    {
      "modelName": "Nombre completo del modelo (ej: JKM550M-72HL4-V)",
      "pmax": 550,
      "shortDesc": "Descripción breve de una línea"
    }
  ]
}`;

return [{
  json: {
    prompt,
    rawText: text  // Guardamos el texto completo para el paso 2
  }
}];

