// ── Parsear respuesta de Ollama para lista de modelos ───────────────────────
const rawText = $('Preparar Prompt: Modelos').first().json.rawText || '';

// La respuesta viene en choices[0].message.content
const content = $input.first().json?.choices?.[0]?.message?.content || '';

let result;
try {
  // Intentar limpiar posibles bloques markdown
  const clean = content
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  result = JSON.parse(clean);
} catch (e) {
  console.error('Error al parsear JSON de Ollama:', content);
  return [{
    json: {
      success: false,
      error: 'El modelo de IA no devolvió un JSON válido. Intenta de nuevo o usa un modelo más potente.',
      manufacturer: 'Desconocido',
      models: [],
      rawText
    }
  }];
}

return [{
  json: {
    success: true,
    manufacturer: result.manufacturer || 'Desconocido',
    models: Array.isArray(result.models) ? result.models : [],
    rawText
  }
}];

// ── Parsear respuesta de Ollama para specs de un modelo ─────────────────────
const content = $input.first().json?.choices?.[0]?.message?.content || '';

let result;
try {
  const clean = content
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  result = JSON.parse(clean);
} catch (e) {
  console.error('Error al parsear JSON de specs:', content);
  return [{
    json: {
      success: false,
      error: 'El modelo de IA no devolvió un JSON válido para las specs. Intenta de nuevo.'
    }
  }];
}

// Normalizar y validar tipos numéricos
const toFloat = (v) => (v !== null && v !== undefined && !isNaN(parseFloat(v))) ? parseFloat(v) : null;
const toInt   = (v) => (v !== null && v !== undefined && !isNaN(parseInt(v)))   ? parseInt(v)   : null;

return [{
  json: {
    success: true,
    manufacturer:   result.manufacturer  || 'Desconocido',
    modelName:      result.modelName     || '',
    cellType:       result.cellType      || 'monocrystalline',
    pmax:           toFloat(result.pmax),
    voc:            toFloat(result.voc),
    isc:            toFloat(result.isc),
    vmp:            toFloat(result.vmp),
    imp:            toFloat(result.imp),
    noct:           toFloat(result.noct),
    tempCoeffIsc:   toFloat(result.tempCoeffIsc),
    tempCoeffVoc:   toFloat(result.tempCoeffVoc),
    tempCoeffPmax:  toFloat(result.tempCoeffPmax),
    efficiency:     toFloat(result.efficiency),
    numCells:       toInt(result.numCells),
    length:         toFloat(result.length),
    width:          toFloat(result.width),
    thickness:      toFloat(result.thickness),
    weight:         toFloat(result.weight),
    tolerance:      toFloat(result.tolerance)
  }
}];
